<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {ChevronDown,Copy,ExternalLink,Search,WalletCards} from 'lucide-vue-next';
import type {CryptoChain,CryptoConfiguredAsset} from '../lib/cryptoPayments';
import {addressHasAsset,chainExplorer,portfolioAmount,type PortfolioBalance,type PortfolioFilter,type PortfolioSnapshot} from '../lib/cryptoPortfolio';
import {stamp} from '../lib/commerce';
import {t} from '../i18n';
const props=defineProps<{chain?:CryptoChain;assets:CryptoConfiguredAsset[];rows:PortfolioBalance[];snapshot?:PortfolioSnapshot;filter:PortfolioFilter;selected:string[];writable:boolean;busy:boolean;loading:boolean;loaded:boolean;hasMore:boolean}>();
const emit=defineEmits<{'update:filter':[value:PortfolioFilter];'update:selected':[value:string[]];copy:[value:string];more:[];withdraw:[]}>();
const assetFilter=ref(''),search=ref('');
watch(()=>props.assets,values=>{if(assetFilter.value&&assetFilter.value!=='native'&&!values.some(value=>value.id===assetFilter.value))assetFilter.value=''});
const visible=computed(()=>props.rows.filter(row=>addressHasAsset(row,assetFilter.value)&&(!search.value||[row.address,row.order_id,row.label,String(row.index)].some(value=>value?.toLowerCase().includes(search.value.toLowerCase())))));
const filters=[{id:'funded',label:'有余额',count:'funded_addresses'},{id:'all',label:'全部地址',count:'total_addresses'},{id:'empty',label:'无余额',count:'empty_addresses'},{id:'failed',label:'查询异常',count:'failed_addresses'}] as const;
const allSelected=computed(()=>visible.value.length>0&&visible.value.every(row=>props.selected.includes(row.address_id)));
function select(id:string,checked:boolean){emit('update:selected',checked?[...new Set([...props.selected,id])]:props.selected.filter(value=>value!==id))}
function selectPage(checked:boolean){const ids=visible.value.map(row=>row.address_id);emit('update:selected',checked?[...new Set([...props.selected,...ids])]:props.selected.filter(value=>!ids.includes(value)))}
function count(key:typeof filters[number]['count']){return props.snapshot?.[key]??'—'}
</script>
<template>
 <section class="wallet-address-list">
  <header><div><h4>{{t('收款地址')}}</h4><p>{{t('保留全部历史订单地址，余额来自整钱包链上快照。')}}</p></div><span v-if="snapshot" class="wallet-address-count">{{t('地址总数')}} <strong>{{snapshot.total_addresses}}</strong></span></header>
  <div class="wallet-address-filters" :aria-label="t('地址余额筛选')"><button v-for="item in filters" :key="item.id" type="button" :aria-pressed="filter===item.id" :class="{active:filter===item.id}" :disabled="busy" @click="emit('update:filter',item.id)">{{t(item.label)}}<span>{{count(item.count)}}</span></button></div>
  <div class="wallet-address-search"><label><Search :size="16"/><input v-model.trim="search" :placeholder="t('搜索已加载的地址、订单或标签')" :aria-label="t('搜索已加载的地址、订单或标签')"/></label><select v-model="assetFilter" :aria-label="t('当前列表币种')"><option value="">{{t('当前列表全部币种')}}</option><option value="native">{{chain?.native_symbol}} · Gas</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{asset.symbol}}</option></select></div>
  <p v-if="assetFilter||search" class="wallet-list-help">{{t('搜索与币种筛选仅作用于已加载地址，上方数量仍为整钱包统计。')}}</p>
  <div v-if="writable" class="wallet-selection-bar"><label><input type="checkbox" :checked="allSelected" :disabled="busy||!visible.length" @change="selectPage(($event.target as HTMLInputElement).checked)"/>{{t('选择当前列表')}}</label><span>{{t('已选择')}} {{selected.length}} {{t('个地址')}}</span><button v-if="selected.length" type="button" :disabled="busy" @click="emit('update:selected',[])">{{t('清空选择')}}</button><button v-if="selected.length" type="button" class="primary" :disabled="busy" @click="emit('withdraw')">{{t('归集选中地址')}}</button></div>
  <p v-if="loading&&!loaded" class="wallet-address-empty" role="status">{{t('正在查询链上余额…')}}</p>
  <div v-else-if="!visible.length" class="wallet-address-empty"><WalletCards :size="27"/><strong>{{t('当前列表没有匹配的地址')}}</strong><p>{{hasMore?t('可继续加载更多地址，或调整筛选条件。'):t('稍后刷新以获取最新链上余额。')}}</p></div>
  <div class="wallet-address-rows"><article v-for="row in visible" :key="row.address_id" :class="{selected:selected.includes(row.address_id)}"><div class="wallet-address-main"><input v-if="writable" type="checkbox" :checked="selected.includes(row.address_id)" :disabled="busy" :aria-label="t('选择地址')+' '+row.index" @change="select(row.address_id,($event.target as HTMLInputElement).checked)"/><span class="wallet-address-avatar"><WalletCards :size="18"/></span><div class="wallet-address-identity"><strong>{{row.label||t('订单收款地址')}} <small>#{{row.index}}</small></strong><code>{{row.address}}</code><span v-if="row.error||row.stale" class="wallet-row-stale">{{row.last_success_at?t('保留最近成功余额'):t('余额尚未确认')}}</span></div><div class="wallet-address-actions"><button type="button" :aria-label="t('复制地址')+' '+row.index" @click="emit('copy',row.address)"><Copy :size="15"/></button><a v-if="chainExplorer(chain?.chain_id||0,row.address)" :href="chainExplorer(chain?.chain_id||0,row.address)" target="_blank" rel="noopener noreferrer" :aria-label="t('在区块浏览器查看地址')+' '+row.index"><ExternalLink :size="15"/></a></div></div><dl class="wallet-row-assets"><div><dt>{{chain?.native_symbol}} · Gas</dt><dd>{{portfolioAmount(row.native_atoms)}}</dd></div><div v-for="token in row.tokens" :key="token.asset_id"><dt>{{token.symbol}}</dt><dd>{{portfolioAmount(token.balance_atoms,token.decimals)}}</dd></div></dl><details class="wallet-address-details"><summary>{{t('地址详情')}}<ChevronDown :size="14"/></summary><dl><div><dt>{{t('派生路径')}}</dt><dd><code>{{row.path}}</code></dd></div><div><dt>{{t('最近成功查询')}}</dt><dd>{{row.last_success_at?stamp(row.last_success_at):'—'}}</dd></div><div><dt>{{t('查询区块')}}</dt><dd>{{row.block_number?'#'+row.block_number:'—'}}</dd></div><div v-if="row.order_id"><dt>{{t('关联订单')}}</dt><dd><RouterLink :to="{path:'/orders',query:{checkout:row.order_id,user_id:row.user_id}}">{{row.order_id}}</RouterLink></dd></div></dl><p v-if="row.error" class="wallet-row-stale">{{t(row.error)}}</p></details></article></div>
  <footer><span>{{t('已加载')}} {{rows.length}} {{t('个地址')}}<template v-if="visible.length!==rows.length"> · {{t('当前显示')}} {{visible.length}}</template></span><button v-if="hasMore" type="button" :disabled="loading" @click="emit('more')">{{loading?t('查询中…'):t('加载更多地址')}}</button></footer>
 </section>
</template>
<style scoped>
.wallet-address-list{display:grid;gap:16px;min-width:0}.wallet-address-list>header{display:flex;align-items:center;justify-content:space-between;gap:14px}.wallet-address-list h4{font-size:18px;margin:0}.wallet-address-list header p{font-size:12px;line-height:1.8;color:var(--secondary);margin:7px 0 0}.wallet-address-count{font-size:12px;white-space:nowrap;color:var(--secondary)}.wallet-address-count strong{font-size:18px;color:var(--text);margin-left:6px}.wallet-address-filters{display:flex;gap:8px;flex-wrap:wrap}.wallet-address-filters button{min-height:40px;font-size:12px;display:flex;gap:8px;align-items:center;background:var(--surface);border:1px solid var(--border);border-radius:9px}.wallet-address-filters button span{min-width:20px;text-align:center;padding:2px 5px;border-radius:5px;background:var(--surface-raised);font-size:11px;font-variant-numeric:tabular-nums}.wallet-address-filters button.active{border-color:var(--accent);background:var(--accent-soft);color:var(--accent-text)}.wallet-address-search{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:10px}.wallet-address-search label{display:flex;align-items:center;gap:8px;padding-left:12px;border:1px solid var(--border);border-radius:9px;background:var(--surface)}.wallet-address-search label svg{flex-shrink:0;color:var(--muted)}.wallet-address-search input{border:0;background:none;width:100%;min-width:0;min-height:44px}.wallet-address-search select{width:100%;min-height:44px;min-width:0}.wallet-selection-bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:11px 13px;background:var(--surface-raised);border-radius:10px;font-size:12px;color:var(--secondary)}.wallet-selection-bar label{display:flex;align-items:center;gap:8px}.wallet-selection-bar input,.wallet-address-main>input{width:17px;height:17px;min-height:17px;flex-shrink:0;accent-color:var(--accent)}.wallet-selection-bar .primary{margin-left:auto}.wallet-selection-bar button{min-height:36px;font-size:12px}.wallet-address-rows{display:grid;gap:12px}.wallet-address-rows>article{border:1px solid var(--border);border-radius:13px;padding:17px;background:var(--surface);min-width:0}.wallet-address-rows>article.selected{border-color:var(--accent);background:color-mix(in srgb,var(--accent-soft) 30%,var(--surface))}.wallet-address-main{display:flex;align-items:center;gap:10px;min-width:0}.wallet-address-avatar{display:grid;place-items:center;width:35px;height:35px;flex-shrink:0;border-radius:10px;color:var(--accent-text);background:var(--accent-soft)}.wallet-address-identity{min-width:0;flex:1}.wallet-address-identity strong{font-size:13px;overflow-wrap:anywhere}.wallet-address-identity strong small{font-size:11px;font-weight:400;color:var(--muted);margin-left:5px}.wallet-address-identity code{display:block;font-size:11px;line-height:1.8;overflow-wrap:anywhere;margin-top:5px}.wallet-address-actions{display:flex;gap:4px;flex-shrink:0}.wallet-address-actions button,.wallet-address-actions a{display:grid;place-items:center;min-width:35px;min-height:38px;color:var(--secondary);padding:7px}.wallet-row-assets{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,130px),1fr));gap:14px;margin:16px 0;padding-top:13px;border-top:1px solid var(--border)}.wallet-row-assets dt,.wallet-address-details dt{font-size:11px;color:var(--secondary)}.wallet-row-assets dd{font-size:14px;line-height:1.6;font-variant-numeric:tabular-nums;overflow-wrap:anywhere;margin:5px 0 0}.wallet-address-details{border-top:1px solid var(--border);padding-top:11px}.wallet-address-details summary{display:flex;align-items:center;gap:5px;width:max-content;font-size:11px;min-height:28px;cursor:pointer;color:var(--secondary)}.wallet-address-details[open] summary svg{transform:rotate(180deg)}.wallet-address-details dl{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:10px 0 0}.wallet-address-details dd{margin:5px 0 0;font-size:11px;line-height:1.8;overflow-wrap:anywhere}.wallet-row-stale{display:block;color:var(--warning);font-size:11px;line-height:1.8;overflow-wrap:anywhere;margin:5px 0 0}.wallet-address-empty{display:grid;justify-items:center;text-align:center;gap:10px;border:1px dashed var(--border);border-radius:13px;padding:30px;color:var(--muted);font-size:12px;line-height:1.8;margin:0}.wallet-address-empty strong{font-size:13px;font-weight:500}.wallet-address-empty p,.wallet-list-help{font-size:11px;color:var(--secondary);line-height:1.8;margin:0}.wallet-address-list footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;font-size:11px;color:var(--secondary)}.wallet-address-list footer button{min-height:44px}@media(max-width:650px){.wallet-address-list>header{align-items:flex-start;flex-direction:column}.wallet-address-search{grid-template-columns:1fr}.wallet-address-filters button{flex:1;justify-content:center}.wallet-address-rows>article{padding:13px}.wallet-address-main{gap:8px;flex-wrap:wrap}.wallet-address-avatar{display:none}.wallet-address-identity{flex-basis:calc(100% - 35px)}.wallet-address-actions{margin-left:auto}.wallet-selection-bar .primary{margin-left:0}.wallet-address-details dl{grid-template-columns:1fr}.wallet-row-assets{gap:11px}}
</style>
